# safepyrun (<=0.2.6) execs a fence with separate globals/locals, so a function or class defined
# in the fence can't see module-level names bound in the same run - `import math` then a `def` that
# calls `math.sqrt` raises `NameError: name 'math' is not defined`. Run everything in one namespace
# (globals is locals) so defs/classes capture top-level imports. Remove once fixed upstream.
import safepyrun.core as _spc

async def _rishi_run_python(code, g=None, ok_dests=None):
    _spc._rp_globals.set(g)
    inject = {'__builtins__': _spc._builtins, '__name__': '<python>'}
    protect = list(inject) + list(_spc._noexport)                 # host helpers must not be shadowed back into g
    saved = {k: g[k] for k in protect if k in g}; had = set(saved)
    g.update(inject)
    async def run(src, is_exec=True):
        comp = compile(src, _spc.srcfn(src), 'exec' if is_exec else 'eval', flags=ast.PyCF_ALLOW_TOP_LEVEL_AWAIT)
        r = eval(comp, g)                                         # one namespace: defs/classes see top-level imports
        return (await r) if inspect.isawaitable(r) else r
    tree = ast.parse(code)
    warnings.filterwarnings('ignore', category=SyntaxWarning)
    res = None
    if tree.body and isinstance(tree.body[-1], ast.Expr):
        last = tree.body.pop()
        if tree.body: await run(ast.unparse(ast.Module(tree.body, [])))
        res = await run(ast.unparse(ast.Expression(last.value)), False)
    else: await run(code)
    for k in protect:                                             # restore injected/host names to pre-run state
        if k in had: g[k] = saved[k]
        else: g.pop(k, None)
    return res

setattr(_spc, '__run_python', _rishi_run_python)

