runtimes = {'litert': ('rishi.litert','LitertChat'), 'llama': ('rishi.llama','LlamaChat'),
            'mlx': ('rishi.mlx','MlxChat')}
dflt_runtime = 'litert'
_pats = {'litert': ('.litertlm','litertlm','litert-community','litert-lm'), 'llama': ('.gguf','gguf'),
         'mlx': ('mlx-community','mlx_lm','-mlx','mlx-')}

def split_runtime(model):
    "Split `'runtime/model'` into `(runtime, model)`; the prefix must name a known runtime, else `(None, model)`."
    if isinstance(model, str) and '/' in model:
        b, m = model.split('/', 1)
        if b in runtimes: return b, m
    return None, model

def infer_runtime(model):
    "Guess a runtime from the shape of a model id or path (`.litertlm` vs `.gguf`), else `None`."
    s = str(model or '').lower()
    if not s: return None
    return next((b for b, ps in _pats.items() if any(p in s for p in ps)), None)

def resolve_runtime(model=None, runtime=None, model_path=None):
    "Resolve `(runtime, model)` from an explicit `runtime`, a `runtime/` prefix, or the id/path shape."
    pre, model = split_runtime(model)
    nm = runtime or pre or infer_runtime(model) or infer_runtime(model_path)
    if nm is None and model is None and model_path is None: nm = dflt_runtime
    if nm is None: raise ValueError(
        f"Can't tell which backend {model!r} needs. Pass runtime={'|'.join(map(repr, runtimes))}, prefix "
        f"the name (e.g. 'llama/{model}'), or give a full repo id or path (.litertlm / .gguf / an mlx repo).")
    if nm not in runtimes: raise ValueError(f"Unknown runtime {nm!r}; known runtimes: {', '.join(runtimes)}.")
    return nm, model

def _runtime_mod(nm):
    "Import and return the backend module for `nm`, with an actionable error when its deps are missing."
    try: return import_module(runtimes[nm][0])
    except ImportError as e:
        raise ImportError(f"The {nm!r} runtime is unavailable ({e}). "
                          f"Install it with: pip install \'rishi[{nm}]\'") from None

def get_runtime(nm):
    "The `Chat` subclass for runtime `nm` (imports the backend module lazily)."
    return getattr(_runtime_mod(nm), runtimes[nm][1])

def _is_path(model):
    "Does `model` name a local file rather than a hub repo id?"
    return bool(model) and (str(model).lower().endswith(('.gguf', '.litertlm')) or Path(model).exists())

def _mk_obj(schema, d):
    "Build `schema` from json-decoded `d`, rebuilding nested dataclasses; non-dict values pass through."
    if not isinstance(d, dict): return d
    if is_dataclass(schema):
        hints = get_type_hints(schema)
        return schema(**{k: (_mk_obj(hints[k], v) if k in hints else v) for k, v in d.items()})
    return schema(**d)

