class ToolLoopMixin:
    """The Python-side tool loop, for backends that get tool calls back as data (llama, mlx).

    The backend supplies one wire call - `_model_step(max_output_tokens) -> Resp` and
    `_stream_step(max_output_tokens)`, a generator of chunk dicts that leaves the merged `Resp` on
    `self._step_res` - plus a `ns` tool namespace. Backends holding conversation state of their own
    also override `_recreate_conv`."""
    _ctx_tokens = 0

    def call_tool(self, tc):
        "Run one approved tool call against `self.ns`; an exception comes back as an error string."
        try: return call_func(tc['function']['name'], tc['function']['arguments'], ns=self.ns)
        except Exception as e: return f"{type(e).__name__}: {e}"

    def _approve1(self, tc):
        "Fire `before_tool_calls`, then check `tc` against HITL approval and the tool-call budget."
        self.turn_tc = tc
        for _ in run_cbs(self, 'before_tool_calls'): pass
        over = self._budget_exceeded or (self.max_steps is not None and self._steps >= self.max_steps)
        ok = False if over else (self.approve is None or self.approve(tc))
        if ok: self._steps += 1
        else: self._budget_exceeded = self._budget_exceeded or over
        return ok, (budget_msg_ if over else 'Denied by human operator')

    def _record_tool(self, tc, out):
        "Truncate an over-long result, record it in `hist`, and fire `after_tool_calls`."
        if self.tool_max_len and isinstance(out, str) and len(out) > self.tool_max_len:
            out = out[:self.tool_max_len] + ' ...[truncated]'
        self.turn_tc, self.turn_tool_result = tc, out
        self.hist.append({'role': 'tool', 'tool_call_id': tc.get('id'),
                          'name': tc['function'].get('name', ''), 'content': str(out)})
        for _ in run_cbs(self, 'after_tool_calls'): pass

    def _run_tools(self, res):
        "Record `res`, approve its calls in order, run the approved ones, then record results in call order."
        self.hist.append(res)
        tcs = res.get('tool_calls') or []
        oks = [self._approve1(tc) for tc in tcs]     # sequential: HITL stays ordered, budget counts each call once
        todo = [tc for tc, (ok, _) in zip(tcs, oks) if ok]
        if self.parallel_tools and len(todo) > 1:
            with ThreadPoolExecutor(max_workers=len(todo)) as ex: outs = list(ex.map(self.call_tool, todo))
        else: outs = [self.call_tool(tc) for tc in todo]
        outs = iter(outs)
        for tc, (ok, denial) in zip(tcs, oks): self._record_tool(tc, next(outs) if ok else denial)

    def _recreate_conv(self):
        "Rebuild backend conversation state from `self.hist`. A no-op for backends that re-send the whole message list on every call (llama, mlx); litert recreates its `Conversation`."
        pass

    def _recover_context(self, err, max_output_tokens=None, keep_last=4, mx=500):
        "Context window full mid-turn: shrink the oldest tool results, rebuild backend state, and ask for a summary rather than raising."
        idxs = [i for i, m in enumerate(self.hist) if m.get('role') == 'tool']
        for i in (idxs[:-keep_last] if keep_last else idxs):
            c = self.hist[i].get('content')
            if isinstance(c, str) and len(c) > mx:
                self.hist[i]['content'] = c[:mx] + ' ...[truncated to recover context]'
        self._budget_exceeded = self._final_sent = True    # no more tools, and this *is* the final round
        self._recreate_conv()
        self.hist.append(mk_oai_msg(self.final_prompt))
        try: return self._model_step(max_output_tokens)
        except Exception as e:
            raise ContextWindowExceededError(f"could not recover after truncating tool results: {err}") from err

    def _finish_turn(self, res, us):
        "Shared tail: total the turn's usage, record the response, fire `after_response`."
        if (u := sum_usage(us)): res['usage'] = u
        self._ctx_tokens = (us[-1] or {}).get('total_tokens', self._ctx_tokens)
        self.turn_res = res
        self.hist.append(res)

    def _send(self, msg, max_output_tokens=None):
        'Send one message, looping until the model stops calling tools or the budget ends the turn.'
        self.turn_msg = self.mk_msg(msg)
        for _ in run_cbs(self, 'before_send'): pass
        if self.turn_msg is not None: self.hist.append(self.turn_msg)
        us = []
        while True:
            try: res = self._model_step(max_output_tokens)
            except Exception as e:
                if not is_ctx_error(self, e): raise
                res = self._recover_context(e, max_output_tokens)
            us.append(res.get('usage'))
            if not res.get('tool_calls') or self._budget_exceeded: break
            self._run_tools(res)
            if self._budget_exceeded: break     # budget ran out mid-round; `__call__` sends `final_prompt`
        self._finish_turn(res, us)
        for _ in run_cbs(self, 'after_response'): pass
        return self.turn_res

    def _stream(self, msg, max_output_tokens=None, cbs=None):
        'Stream a turn as markdown chunks; per-call `cbs` live only for this turn.'
        added = self.add_cbs(cbs); prev = getattr(self, '_streaming', False); self._streaming = True
        try:
            self.turn_msg = self.mk_msg(msg)
            for _ in run_cbs(self, 'before_send'): pass
            if self.turn_msg is not None: self.hist.append(self.turn_msg)
            fmt, us = StreamFormatter(), []
            while True:
                try:
                    for o in self._stream_step(max_output_tokens):
                        if (s := fmt.format_item(o)): yield s
                except Exception as e:
                    if not is_ctx_error(self, e): raise
                    res = self._recover_context(e, max_output_tokens)
                    yield StreamFormatter().format_item(res)
                    us.append(res.get('usage')); break
                if fmt._inthink: fmt._inthink = False; yield '\n\n'
                res = self._step_res
                us.append(res.get('usage'))
                if not res.get('tool_calls') or self._budget_exceeded: break
                for tc in res['tool_calls']:
                    yield fmt.format_item({'content': [{'type': 'tool_call', 'name': tc['function'].get('name', ''),
                                                        'arguments': tc['function'].get('arguments', {})}]})
                self._run_tools(res)
                if self._budget_exceeded: break
            self._finish_turn(res, us)
            yield from run_cbs(self, 'after_response')
            return self.turn_res   # stream's final Resp, captured by SaveReturn / AsyncChat `.value`
        finally: self._streaming = prev; self.remove_cbs(added)

# %% ../nbs/00_core.ipynb #core_async
class AsyncChat(GetAttr):
    "Async twin of `Chat` for either backend; blocking calls run in a worker thread."
    _default = 'chat'
    def __init__(self, model=None, *, runtime=None, **kw):
        self.chat = model if hasattr(model, '_send') else Chat(model, runtime=runtime, **kw)
    async def __call__(self, msg=None, stream=False, max_output_tokens=None, cbs=None):
        'Run one chat turn; `await` the result (an async chunk iterator when `stream=True`, whose `.value` holds the final `Resp` once drained).'
        if stream: return self._astream(msg, max_output_tokens, cbs)
        return await asyncio.to_thread(self.chat, msg, False, max_output_tokens, cbs)
    @asave_iter
    async def _astream(it, self, msg, max_output_tokens=None, cbs=None):
        "Drive the sync stream in a worker thread; the returned iterator's `.value` holds the turn's final `Resp`."
        g = SaveReturn(self.chat(msg, stream=True, max_output_tokens=max_output_tokens, cbs=cbs))
        gi, done = iter(g), object()
        while (o := await asyncio.to_thread(next, gi, done)) is not done: yield o
        it.value = g.value   # async generators can't `return` a value; hand the Resp back on the iterator
    def close(self): self.chat.close()
    async def __aenter__(self): return self
    async def __aexit__(self, *exc): self.close()

async def adisplay_stream(chunks):
    "Async twin of `display_stream`: drive an async chunk stream - or the awaitable that yields one (`achat(msg, stream=True)`) - to completion, live-rendering in a notebook when possible; returns the full markdown."
    if not hasattr(chunks, '__aiter__'): chunks = await chunks
    from IPython.display import display, Markdown
    h, md = display(Markdown(''), display_id=True),''
    async for c in chunks:
        md += c
        if h is not None: h.update(Markdown(md))
    return md

